func (q *Queries) SetInstanceIdentity(ctx context.Context, arg SetInstanceIdentityParams) error {
	_, err := q.db.Exec(ctx, setInstanceIdentity, arg.DeviceIdentity, arg.Locale, arg.ID)
	return err
}

const setInstanceState = `-- name: SetInstanceState :execrows
UPDATE instances SET state = $1, updated_at = now()
WHERE id = $2 AND state = $3
`

type SetInstanceStateParams struct {
	ToState   string
	ID        uuid.UUID
	FromState string
}

func (q *Queries) SetInstanceState(ctx context.Context, arg SetInstanceStateParams) (int64, error) {
	result, err := q.db.Exec(ctx, setInstanceState, arg.ToState, arg.ID, arg.FromState)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

