const updateInstanceSettings = `-- name: UpdateInstanceSettings :one
UPDATE instances
SET display_name    = COALESCE($1::text, display_name),
    enabled         = COALESCE($2::boolean, enabled),
    send_only       = COALESCE($3::boolean, send_only),
    phone_number_id = COALESCE($4::text, phone_number_id),
    updated_at      = now()
WHERE id = $5
RETURNING id, organization_id, client_id, core_id, core_name, display_name, provider, send_only, enabled, phone_number_id, device_identity, state, last_status, last_status_at, status_checked_at, alert_kind, alert_opened_at, alerted_at, alert_attempts, alert_next_attempt_at, created_at, updated_at, locale
`

type UpdateInstanceSettingsParams struct {
	DisplayName   *string
	Enabled       *bool
	SendOnly      *bool
	PhoneNumberID *string
	ID            uuid.UUID
}

func (q *Queries) UpdateInstanceSettings(ctx context.Context, arg UpdateInstanceSettingsParams) (Instance, error) {
	row := q.db.QueryRow(ctx, updateInstanceSettings,
		arg.DisplayName,
		arg.Enabled,
		arg.SendOnly,
		arg.PhoneNumberID,
		arg.ID,
	)
	var i Instance
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.ClientID,
		&i.CoreID,
		&i.CoreName,
		&i.DisplayName,
		&i.Provider,
		&i.SendOnly,
		&i.Enabled,
		&i.PhoneNumberID,
		&i.DeviceIdentity,
		&i.State,
		&i.LastStatus,
		&i.LastStatusAt,
		&i.StatusCheckedAt,
		&i.AlertKind,
		&i.AlertOpenedAt,
		&i.AlertedAt,
		&i.AlertAttempts,
		&i.AlertNextAttemptAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Locale,
	)
	return i, err
}
